def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Nonzero contiguous runs on the two border rows are templates.
    templates = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            run = []
            while c < w and grid[r][c] != 0:
                run.append(grid[r][c])
                c += 1
            templates.append(run)
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            seq = next((s for s in templates if color in s), None)
            if seq is None:
                continue
            start = c - seq.index(color)
            for i, v in enumerate(seq):
                x = start + i
                if 0 <= x < w:
                    out[r][x] = v
    return out
